test "$(git rev-parse HEAD)" = "4b06a39ebdb8a99d5544b27c8a52f33ad8e42440"
test -z "$(git status --porcelain --untracked-files=all)"
python3 -B - <<'PY'
import hashlib,subprocess,difflib
from pathlib import Path
p="server/tests/server-command-tool-runtime.test.cjs"
h=Path(p).read_bytes()
s=subprocess.check_output(["docker","exec","debug-ai-sandbox-runner-1","cat","/app/"+p])
print("HOST_TEST_SHA256="+hashlib.sha256(h).hexdigest())
print("SANDBOX_TEST_SHA256="+hashlib.sha256(s).hexdigest())
old=subprocess.check_output(["git","show","70689ec0fdb9201742625d5d8a0054feeb31320d:"+p])
print("SANDBOX_MATCH_PREVIOUS="+str(s==old))
print("HOST_MATCH_PREVIOUS="+str(h==old))
for line in list(difflib.unified_diff(h.decode().splitlines(),s.decode().splitlines(),fromfile="host",tofile="sandbox",n=2))[:100]:
 print(line)
